# owner: platform
"""Find the stretches of opening hours nobody is covering."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


class OutsideHoursError(ValueError):
    """A worked span reaches outside the opening hours."""


def _find_gaps(spans: List[Span], opening: Span) -> List[Span]:
    edges = [opening.start]
    for span in merge_spans(spans):
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(begin, stop) for begin, stop in pairs if begin < stop]


# ---
def gap_labels(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as gap 12:00-13:00 (60 min)."""
    spans = list(worked)
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise OutsideHoursError(format_span(span))
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in _find_gaps(spans, opening)
    ]
EOF
cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import OutsideHoursError, gap_labels

OPEN = parse_span("08:00-18:00")


class GapTests(unittest.TestCase):
    def test_middle_gap(self):
        worked = [parse_span("08:00-12:00"), parse_span("13:00-18:00")]
        self.assertEqual(
            gap_labels(worked, OPEN), ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = [parse_span("09:00-11:00"), parse_span("10:00-12:00")]
        self.assertEqual(
            gap_labels(worked, OPEN),
            ["gap 08:00-09:00 (60 min)", "gap 12:00-18:00 (360 min)"],
        )

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(gap_labels([OPEN], OPEN), [])

    def test_nobody_worked(self):
        self.assertEqual(
            gap_labels([], OPEN), ["gap 08:00-18:00 (600 min)"]
        )

    def test_outside_hours_raises(self):
        for bad in (Span(420, 600), Span(600, 1100)):
            with self.assertRaises(OutsideHoursError):
                gap_labels([bad], OPEN)


if __name__ == "__main__":
    unittest.main()
EOF
